    50  mrb_packed_int_encode(uint32_t num, uint8_t *p, uint8_t *pend)
    51  {
    52    size_t llen = 0;
    53
    54    do {
    55      uint8_t byte = num & 0x7f;
    56      num >>= 7;
    57      if (num != 0) byte |= 0x80;
    58      if (p < pend) *p++ = byte;
    59      llen++;
    60    } while (num != 0);
